    $this->assertSame('foo bar', Str::trim('foo bar'));
    $this->assertSame(' foo bar ', Str::trim(' foo bar ', ''));
    $this->assertSame('foo bar', Str::trim(' foo bar ', ' '));
    $this->assertSame('foo  bar', Str::trim('-foo  bar_', '-_'));

    $this->assertSame('foo    bar', Str::trim(' foo    bar '));

