    $this->assertSame('だ', Str::trim('だ'));
    $this->assertSame('ム', Str::trim('ム'));
    $this->assertSame('だ', Str::trim('   だ    '));
    $this->assertSame('ム', Str::trim('   ム    '));

    $this->assertSame(
        'foo bar',
        Str::trim('
            foo bar
        ')
    );
